"""Regenerate live-shape.json: stored rweb16 turns run through the backend's own assembly.

Chat: rweb16 per-turn states (the graph's last AIMessage at verify time and the
verifier's report), assembled as app/api/server.py does it::

    written = reply_segments.of_message(ai_msg)
    presentable_segments(text_of(written), verification_report, written)

and returned as the API's assistant message (reply_segments.presented).

Upload: the stored deferred-profile response of an rweb16 upload (charts,
profile overview, dataset size) through visualization_agent.mark_upload_commentary,
the last step of the upload assembly.

Only what the UI renders is kept: text, kinds, segments, and the card fields
the components read. No graph state, no session or connection data. Run
~/avaloka-work/tools/fixture_secret_scan.sh on the tree before committing.

Needs C1's presentable_segments and C2's mark_upload_commentary in the tree it
runs from. From the repo root, in the CI image:
    python -I ui/tests/fixtures/commentary/generate_live_shape.py STATES_DIR
STATES_DIR defaults to ~/avaloka-work/states/rweb16.
"""

from __future__ import annotations

import json
import os
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[4]
sys.path.insert(0, str(ROOT))

from langchain_core.messages import AIMessage  # noqa: E402

from app.agents.claim_verifier import presentable_segments  # noqa: E402
from app.agents.visualization_agent import mark_upload_commentary  # noqa: E402
from app.api import reply_segments as rs  # noqa: E402

OUT = Path(__file__).with_name("live-shape.json")

#: (fixture key, state file): bullets and a withheld claim; bullets and two
#: findings; a model-written table with a numbered list (rw7b, rw7c).
CHAT_TURNS = (
    ("rw7b_stroke_ask", "rw7b/stroke/ask.json"),
    ("rw7b_nullxlsx_reply", "rw7b/nullxlsx/reply.json"),
    ("rw7b_related_tables", "rw7b/related/ask_tables.json"),
    ("rw7c_related_tables", "rw7c/related/ask_tables.json"),
)
UPLOAD = "rw7b/stroke/upload.json"

CHART_KEYS = ("id", "type", "title", "insight", "reason", "headline", "insight_facts", "insight_source",
              "title_segments", "insight_segments", "headline_segments")
OVERVIEW_TEXT = ("readiness_reasoning", "domain_reasoning")
OVERVIEW_LISTS = ("red_flags", "concerns", "strengths", "quick_wins", "analysis_suggestions")


def _chat_turn(state: dict) -> dict:
    messages = (state.get("verify_state") or {}).get("messages") or []
    ai = [m for m in messages if isinstance(m, dict) and m.get("type") == "ai"][-1]
    report = (state.get("verify_output") or {}).get("verification_report")
    written = rs.of_message(AIMessage(content=ai["content"]))
    message = rs.presented(presentable_segments(rs.text_of(written), report, written))
    rs.check(message["content"], message["reply_segments"])
    return {"question": state.get("question_sent"), "role": "assistant", **message}


def _upload(state: dict) -> dict:
    viz = state["profile_response"]["body"]["visualization_config"]
    dataset = viz.get("dataset") or {}
    total_rows, columns = dataset.get("total_rows"), dataset.get("columns") or []
    mark_upload_commentary(viz, total_rows, len(columns))
    overview = viz.get("profile_overview") or {}
    keep_ov = {"readiness_score": overview.get("readiness_score"), "domain": overview.get("domain")}
    for key in OVERVIEW_TEXT + OVERVIEW_LISTS:
        for k in (key, key + "_segments"):
            if overview.get(k) is not None:
                keep_ov[k] = overview[k]
    return {
        "dataset_id": "rweb16-stroke",
        "filename": "healthcare-dataset-stroke-data.csv",
        "visualization_config": {
            "dataset": {"total_rows": total_rows, "columns": columns},
            "charts": [{k: c[k] for k in CHART_KEYS if k in c} for c in viz.get("charts") or []],
            "profile_overview": keep_ov,
            "upload_message": viz["upload_message"],
            "upload_message_segments": viz["upload_message_segments"],
        },
    }


def main() -> None:
    states = Path(sys.argv[1] if len(sys.argv) > 1 else os.path.expanduser("~/avaloka-work/states/rweb16"))

    def load(rel: str) -> dict:
        return json.loads((states / rel).read_text())

    out = {
        "_source": ("Generated by generate_live_shape.py from rweb16 per-turn states "
                    f"({', '.join(f for _, f in CHAT_TURNS)}; {UPLOAD}) through "
                    "claim_verifier.presentable_segments (as app/api/server.py assembles the reply) and "
                    "visualization_agent.mark_upload_commentary. Do not edit by hand."),
        "chat": {key: _chat_turn(load(rel)) for key, rel in CHAT_TURNS},
        "upload": _upload(load(UPLOAD)),
    }
    OUT.write_text(json.dumps(out, indent=1, ensure_ascii=False) + "\n")
    print(f"wrote {OUT.relative_to(ROOT)} ({OUT.stat().st_size} bytes)")


if __name__ == "__main__":
    main()
